const provenance = { editedBy: "OnCo cooperative groups migration (row 251: institution consortium records moved to cooperative-group companies)", editedOn: "2026-09-25" };

type C = Omit<CompanyInput, "kind" | "provenance" | "companyType">;
const grp = ({ tags = [], ...x }: C): CompanyInput => ({ kind: "company", provenance, companyType: "cooperative-group", tags: [...TAGS, ...tags.filter((t) => !TAGS.includes(t))], ...x });

